import { createHash, randomUUID } from 'node:crypto';
import { createReadStream, createWriteStream } from 'node:fs';
import { mkdir, readdir, rename, rm, stat, writeFile } from 'node:fs/promises';
import { dirname, join, resolve, sep } from 'node:path';
import type { Readable } from 'node:stream';
import { pipeline } from 'node:stream/promises';
import { Transform } from 'node:stream';
import { badRequest, DomainError, tooLarge, unavailable } from '../domain/errors.js';
import { SNIFF_BYTES, type Sniffed, sniff } from './sniff.js';

/** Keys are generated by the server only: "<report uuid>/<attachment uuid>.<ext>". */
const KEY = /^[0-9a-f-]{36}\/[0-9a-f-]{36}\.[a-z0-9]{2,5}$/;

export type StoredFile = { tmpPath: string; size: number; sha256: string; type: Sniffed };

/** What the client is told; the details (path, errno) go to the log. */
export const MEDIA_UNAVAILABLE =
  'media storage is not available (the media directory is missing, full or not writable), so files cannot be saved; ask the administrator to check TABULA_MEDIA_DIR';

/** Errors that mean the directory itself is unusable, not that one upload was bad. */
const STORAGE_ERRORS = new Set(['EACCES', 'EPERM', 'EROFS', 'ENOENT', 'ENOTDIR', 'ENOSPC', 'EDQUOT']);

/**
 * Attachments on the local disk (a Docker volume). Uploads stream to a temporary file first, so a broken or
 * oversized upload never leaves a half-written attachment behind.
 */
export class MediaStore {
  readonly root: string;
  /** Set once a write test passed; cleared when a write fails because of the directory. */
  private writable = false;
  constructor(dir: string, readonly maxBytes: number) {
    this.root = resolve(dir);
  }

  private get tmpDir(): string {
    return join(this.root, '.tmp');
  }

  /**
   * At startup: create the directory, delete temporary files left by uploads that a restart interrupted and test
   * that it is writable. Returns the problem (for the log), or null. Tabula keeps running without media storage:
   * only uploads and new frames fail, with a 503.
   */
  async startup(): Promise<string | null> {
    try {
      await mkdir(this.tmpDir, { recursive: true });
      for (const name of await readdir(this.tmpDir)) await rm(join(this.tmpDir, name), { recursive: true, force: true });
    } catch (e) {
      return errorText(e);
    }
    return this.probe();
  }

  private async probe(): Promise<string | null> {
    try {
      await mkdir(this.tmpDir, { recursive: true });
      const file = join(this.tmpDir, `probe-${randomUUID()}`);
      await writeFile(file, '');
      await rm(file);
      this.writable = true;
      return null;
    } catch (e) {
      this.writable = false;
      return errorText(e);
    }
  }

  /** Before a write: 503 when the directory is unusable (tested again each time until it works). */
  async ensureWritable(): Promise<void> {
    if (this.writable) return;
    const problem = await this.probe();
    if (problem) throw Object.assign(unavailable(MEDIA_UNAVAILABLE), { cause: new Error(`${this.root}: ${problem}`) });
  }

  /** A filesystem error caused by the directory becomes a 503 (and the next write tests it again). */
  private storageError(e: unknown): unknown {
    if (e instanceof DomainError) return e;
    const code = (e as NodeJS.ErrnoException).code;
    if (code && STORAGE_ERRORS.has(code)) {
      this.writable = false;
      return Object.assign(unavailable(MEDIA_UNAVAILABLE), { cause: e });
    }
    return e;
  }

  /** A fresh path in the temporary directory. */
  tempPath(): string {
    return join(this.tmpDir, randomUUID());
  }

  /** Size and SHA-256 of a file (after ffmpeg rewrote an upload). */
  async digest(file: string): Promise<{ size: number; sha256: string }> {
    const hash = createHash('sha256');
    let size = 0;
    for await (const chunk of createReadStream(file)) {
      size += (chunk as Buffer).length;
      hash.update(chunk as Buffer);
    }
    return { size, sha256: hash.digest('hex') };
  }

  path(key: string): string {
    if (!KEY.test(key)) throw new Error(`invalid storage key ${key}`);
    const p = resolve(this.root, key);
    if (!p.startsWith(this.root + sep)) throw new Error(`storage key escapes the media directory: ${key}`);
    return p;
  }

  /** Stream an upload into a temporary file, checking the size limit and detecting the type from the first bytes. */
  async receive(body: Readable, declared?: string): Promise<StoredFile> {
    await this.ensureWritable();
    await mkdir(this.tmpDir, { recursive: true }).catch((e) => { throw this.storageError(e); });
    const tmpPath = this.tempPath();
    const hash = createHash('sha256');
    let size = 0;
    let head = Buffer.alloc(0);
    let type: Sniffed | null = null;
    const max = this.maxBytes;
    const meter = new Transform({
      transform(chunk: Buffer, _enc, done) {
        size += chunk.length;
        if (size > max) return done(tooLarge(`the file is larger than the limit of ${Math.round(max / 1024 / 1024)} MB`));
        if (!type) {
          if (head.length < SNIFF_BYTES) head = Buffer.concat([head, chunk.subarray(0, SNIFF_BYTES - head.length)]);
          if (head.length >= SNIFF_BYTES || head.length >= 12) {
            type = sniff(head, declared);
            if (!type && head.length >= SNIFF_BYTES) {
              return done(badRequest('unsupported file type: upload a photo (JPEG, PNG, WebP, GIF, HEIC), a video (MP4, MOV, WebM) or audio (M4A, MP3, WebM, Ogg, WAV, AAC)'));
            }
          }
        }
        hash.update(chunk);
        done(null, chunk);
      },
    });
    try {
      await new Promise<void>((done, fail) => {
        const out = createWriteStream(tmpPath);
        let failed = false;
        // Never destroy the request on a refusal: the client must still get the 400/413 answer. Stop writing,
        // let the rest of the body drain, and the route closes the connection after replying.
        const stop = (e: unknown) => {
          if (failed) return;
          failed = true;
          body.unpipe(meter);
          body.resume();
          meter.destroy();
          // The file is opened asynchronously: reject only after the stream is closed, or the open can still create
          // the file after the caller removed it and leave a stray temporary file behind.
          if (out.closed) return fail(e);
          out.once('close', () => fail(e));
          out.destroy();
        };
        body.on('error', stop);
        body.on('aborted', () => stop(badRequest('the upload was interrupted')));
        meter.on('error', stop);
        out.on('error', stop);
        out.on('finish', () => !failed && done());
        body.pipe(meter).pipe(out);
      });
      type ??= sniff(head, declared);
      if (size === 0) throw badRequest('the file is empty');
      if (!type) throw badRequest('unsupported file type: upload a photo, a video or audio');
      return { tmpPath, size, sha256: hash.digest('hex'), type };
    } catch (e) {
      await rm(tmpPath, { force: true }).catch(() => {});
      throw this.storageError(e);
    }
  }

  async commit(tmpPath: string, key: string): Promise<void> {
    const dest = this.path(key);
    try {
      await mkdir(dirname(dest), { recursive: true });
      await rename(tmpPath, dest);
    } catch (e) {
      throw this.storageError(e);
    }
  }

  async writeBuffer(key: string, data: Buffer): Promise<void> {
    const dest = this.path(key);
    await this.ensureWritable();
    const tmp = this.tempPath();
    try {
      await mkdir(dirname(dest), { recursive: true });
      await pipeline(async function* () { yield data; }, createWriteStream(tmp));
      await rename(tmp, dest);
    } catch (e) {
      await rm(tmp, { force: true }).catch(() => {});
      throw this.storageError(e);
    }
  }

  async discard(tmpPath: string): Promise<void> {
    await rm(tmpPath, { force: true });
  }

  async remove(key: string): Promise<void> {
    await rm(this.path(key), { force: true });
  }

  /** Everything stored for one report (its directory). */
  async removeReport(reportId: string): Promise<void> {
    if (!/^[0-9a-f-]{36}$/.test(reportId)) throw new Error(`invalid report id ${reportId}`);
    await rm(join(this.root, reportId), { recursive: true, force: true });
  }

  async size(key: string): Promise<number | null> {
    try {
      return (await stat(this.path(key))).size;
    } catch {
      return null;
    }
  }

  open(key: string, range?: { start: number; end: number }): Readable {
    return createReadStream(this.path(key), range);
  }
}

const errorText = (e: unknown) => (e as Error).message;
